# Prefix pairs ("vlad"/"vladimir", "dan"/"daniel") don't need an entry; see _first_names_match.
_NICKNAME_GROUPS = (
    {"robert", "rob", "bob", "bobby", "robbie"},
    {"william", "will", "bill", "billy", "liam"},
    {"james", "jim", "jimmy", "jamie"},
    {"michael", "mike", "mick"},
    {"richard", "rick", "dick", "rich"},
    {"edward", "ed", "eddie", "ted", "ned"},
    {"elizabeth", "liz", "beth", "betsy", "eliza"},
    {"margaret", "maggie", "peggy", "meg"},
    {"katherine", "catherine", "kate", "katie", "kathy", "cathy"},
    {"anthony", "tony"},
    {"andrew", "andy", "drew"},
    {"steven", "stephen", "steve"},
    {"joseph", "joe", "joey"},
    {"thomas", "tom", "tommy"},
    {"charles", "charlie", "chuck"},
    {"john", "jack", "johnny"},
    {"alexander", "alexandra", "alex", "sasha"},
    {"jennifer", "jen", "jenny"},
    {"christopher", "chris"},
    {"susan", "sue", "suzy"},
)
_NICKNAMES: dict[str, frozenset[str]] = {
    name: frozenset(group) for group in _NICKNAME_GROUPS for name in group
}

# A prefix shorter than this is too ambiguous to merge on ("Al" could be Alan or Alice).
_MIN_PREFIX_LEN = 3
# Whole-name similarity at or above this, without a merge, is flagged for human review.
_POSSIBLE_DUPLICATE_RATIO = 0.85
# Same first initial plus last names at least this similar is also flagged.
_SIMILAR_LAST_NAME_RATIO = 0.8


def _ratio(a: str, b: str) -> float:
    return SequenceMatcher(None, a, b).ratio()


class Identity(StrEnum):
    SAME = "same"  # merge automatically
    POSSIBLE_DUPLICATE = "possible_duplicate"  # keep separate, list in VALIDATION.md
    DIFFERENT = "different"


@dataclass(frozen=True)
class NameRecord:
    company_id: int
    full_name: str
    functions: frozenset[str] = field(default_factory=frozenset)

    @property
    def tokens(self) -> list[str]:
        return normalize_name(self.full_name).split()


def _first_names_match(a: str, b: str) -> bool:
    if a == b:
        return True
    short, long = sorted((a, b), key=len)
    if len(short) >= _MIN_PREFIX_LEN and long.startswith(short):
        return True
    return b in _NICKNAMES.get(a, frozenset())


def compare_identity(a: NameRecord, b: NameRecord) -> Identity:
    """Narrow, deterministic same-person rule.

    SAME only when all hold: same company; identical normalized names, OR same last name +
    first names that match by prefix (Vlad/Vladimir) or the nickname map + at least one
    overlapping role function. Anything close that misses a condition is
    POSSIBLE_DUPLICATE so a human decides; a wrong merge would mix two people's facts.
    """
    if a.company_id != b.company_id:
        return Identity.DIFFERENT
    ta, tb = a.tokens, b.tokens
    if not ta or not tb:
        return Identity.DIFFERENT
    if ta == tb:
        return Identity.SAME

    same_last = ta[-1] == tb[-1]
    first_match = _first_names_match(ta[0], tb[0])
    function_overlap = bool(a.functions & b.functions)

    if same_last and first_match and function_overlap:
        return Identity.SAME
    same_initial = ta[0][0] == tb[0][0]
    if same_last and (first_match or same_initial):
        return Identity.POSSIBLE_DUPLICATE
    if same_initial and _ratio(ta[-1], tb[-1]) >= _SIMILAR_LAST_NAME_RATIO:
        return Identity.POSSIBLE_DUPLICATE  # e.g. Quirk / Quirke
    ratio = _ratio(" ".join(ta), " ".join(tb))
    if ratio >= _POSSIBLE_DUPLICATE_RATIO:
        return Identity.POSSIBLE_DUPLICATE
    return Identity.DIFFERENT


# ---------------------------------------------------------------------------- resolution

STALE_AFTER_DAYS = 548  # 18 months
PROXY_FORM = "DEF 14A"
_CONFIDENCE_RANK = {"low": 0, "medium": 1, "high": 2}
_SENIORITY_RANK = {"c_level": 0, "founder": 1, "vp": 2, "head": 3}


def _ordinal(iso: str | None) -> int:
    return date.fromisoformat(iso).toordinal() if iso else 0


def _claim_sort_key(c: Claim) -> tuple:
    """Best evidence first: source priority, then newest dated, then URL for stability."""
    return (SOURCE_PRIORITY[c.doc.source_type], -_ordinal(c.published_at), c.doc.url, c.title)


def _is_proxy(c: Claim) -> bool:
    return c.doc.source_type == "sec_filing" and c.doc.meta.get("form") == PROXY_FORM


def _blocked_host(c: Claim) -> bool:
    return str(c.doc.meta.get("direct_fetch", "")).startswith("blocked")


@dataclass
class ResolvedRole:
    title: str
    function: str
    seniority: str
    is_current: bool
    as_of: str | None
    confidence: str
    claims: list[Claim]
    note: str = ""


@dataclass
class ResolvedPerson:
    full_name: str
    claims: list[Claim]
    roles: list[ResolvedRole]
    confidence: str
    profile_url: str | None = None
    location: str | None = None
    location_claim: Claim | None = None
    bio: str | None = None
    bio_claim: Claim | None = None
    name_claim: Claim | None = None  # the claim the displayed name comes from

    @property
    def is_current(self) -> bool:
        return any(r.is_current for r in self.roles)


@dataclass
class Resolution:
    people: list[ResolvedPerson]
    review: dict[str, list[dict[str, Any]]]


def cluster_claims(claims: list[Claim], company_id: int = 0) -> list[list[Claim]]:
    """Group claims into people with compare_identity (SAME only), best evidence first."""
    clusters: list[list[Claim]] = []
    for claim in sorted(claims, key=_claim_sort_key):
        rec = NameRecord(company_id, claim.full_name, frozenset({claim.title_class.function}))
        for cluster in clusters:
            functions = frozenset(c.title_class.function for c in cluster)
            if compare_identity(rec, NameRecord(company_id, cluster[0].full_name, functions)) is (
                Identity.SAME
            ):
                cluster.append(claim)

"""Deterministic title rules (no LLM): is a title in scope, and what seniority/function is it.

In scope: C-level (incl. President, D4), founders, VPs, and Heads. General Counsel and Chief
Legal titles are marked `legal_chief`; resolve.py makes them C-level only if the latest
proxy lists the person as an executive officer, otherwise Head of legal (D4).
Out of scope: board-only roles, plain "Director", managers, individual contributors.
"""

from __future__ import annotations

import re
from dataclasses import dataclass

_C_ACRONYMS = {
    "ceo": "other",
    "cfo": "finance",
    "cto": "engineering",
    "coo": "operations",
    "cmo": "marketing",
    "cpo": "product",
    "ciso": "security",
    "cso": "security",
    "cro": "sales",
    "clo": "legal",
    "chro": "people",
    "cio": "engineering",
    "cdo": "data",
    "cco": "legal",
}

# Checked in order; the first function whose pattern matches the title wins. Sales comes
# before engineering so "Head of Technology Partnerships" is sales, not engineering.
_FUNCTION_PATTERNS: tuple[tuple[str, str], ...] = (
    ("security", r"secur|trust|\bciso\b"),
    ("legal", r"legal|counsel|complian|regulat|corporate affairs|policy|privacy"),
    ("finance", r"financ|account|treasur|controller|investor relations|tax\b|\bfp&a\b"),
    ("people", r"\bpeople\b|human resources|\bhr\b|talent|recruit|culture|workplace"),
    ("data", r"\bdata\b|analytics|machine learning|\bai\b|artificial intelligence"),
    ("design", r"design|\bux\b|creative"),
    ("product", r"product"),
    ("marketing", r"marketing|brand|communications|\bpr\b|growth|content|community"),
    (
        "sales",
        r"sales|revenue|business development|partnership|commercial|go-to-market|\bgtm\b"
        r"|customer success|account",
    ),
    (
        "engineering",
        r"engineer|technolog|technical|information|infrastructure|platform|architect|\bit\b",
    ),
    ("operations", r"operat|customer|support|brokerage|strategy|business"),
)

_BOARD_ONLY = re.compile(
    r"^(?:independent |lead independent |non-executive )?(?:board )?"
    r"(?:director|board member|member of the board|chair(?:man|woman|person)?"
    r"(?: of the board)?)$"
)
_FORMER = re.compile(r"\b(?:former(?:ly)?|ex-|previously|retired|outgoing)\b")


@dataclass(frozen=True)
class TitleClass:
    seniority: str  # c_level | vp | head | founder
    function: str
    also_founder: bool = False  # e.g. "Co-founder & CEO": one c_level role plus a founder role
    legal_chief: bool = False  # General Counsel / Chief Legal Officer: see D4 in resolve.py


def _clean(title: str) -> str:
    t = title.lower().replace("’", "'").replace("–", "-").replace("—", "-")
    t = " ".join(re.sub(r"[^a-z0-9&,'/\- ]", " ", t).split())
    # Plurals from shared titles: "Co-Founders and Co-CEOs" -> "co-founder and co-ceo"
    return re.sub(r"\b(founder|ceo|cfo|cto|coo|officer)s\b", r"\1", t)


def function_for(title: str) -> str:
    t = _clean(title)
    for function, pattern in _FUNCTION_PATTERNS:
        if re.search(pattern, t):
            return function
    return "other"


def mentions_former(title: str) -> bool:
    """'Former CFO', 'ex-VP', 'retired'. ('Interim' is a current role.)"""
    return bool(_FORMER.search(_clean(title)))


def strip_company(title: str, company_name: str | None) -> str:
    """Drop "<Company> <Word>" qualifiers ("Robinhood Financial", "Robinhood UK") so a
    subsidiary's name doesn't decide the function ("Financial" is not finance)."""
    if not company_name:
        return title
    name = re.escape(_clean(company_name).split(" ")[0])
    return " ".join(re.sub(rf"\b{name}(?:\s+[a-z]+)?\b", " ", title).split())


_VP_TOKEN = re.compile(r"\b(?:vice president|vp|svp|evp|avp)\b")
# "President of Robinhood UK", "President, Robinhood Financial": a subsidiary president.
_QUALIFIED_PRESIDENT = re.compile(r"\bpresident\s*(?:,|of\b)")


def classify_title(title: str, company_name: str | None = None) -> TitleClass | None:
    """Seniority and function for an in-scope leadership title, or None if out of scope.

    C-level means the company's own C-suite. A title that also carries a VP token ("Vice
    President and Chief Information Security Officer") or a subsidiary presidency ("President
    of Robinhood UK") is VP-level. General Counsel / Chief Legal Officer is returned as
    C-level with legal_chief=True; resolve.py applies the proxy test (D4)."""
    full = _clean(title)
    if not full or _BOARD_ONLY.match(full):
        return None
    t = strip_company(full, company_name) or full
    founder = bool(re.search(r"\b(?:co-?)?founder\b", t))
    words = set(re.findall(r"[a-z]+", t))

    acronyms = [a for a in _C_ACRONYMS if a in words]
    chief = re.search(r"\bchief\b.*\bofficer\b", t)
    president = (
        re.search(r"(?<!vice )\bpresident\b", t)
        and not re.search(r"\bvice\b", t)
        and not _QUALIFIED_PRESIDENT.search(full)
    )
    counsel = re.search(r"\bgeneral counsel\b", t)
    if (chief or acronyms) and _VP_TOKEN.search(t) and not counsel:
        return TitleClass("vp", function_for(t.replace("chief executive officer", "")),
                          also_founder=founder)  # fmt: skip
    if not (chief or acronyms or president or counsel) and _QUALIFIED_PRESIDENT.search(full):
        return TitleClass("vp", function_for(t.replace("president", "")), also_founder=founder)
    if chief or acronyms or president or counsel:
        if chief:
            # "Chair and Chief Executive Officer" -> other; "Chief Legal ... Officer" -> legal
            function = function_for(t.replace("chief executive officer", ""))
        elif acronyms:
            function = _C_ACRONYMS[acronyms[0]]
        elif counsel:
            function = "legal"
        else:
            function = function_for(t.replace("president", ""))
        legal_chief = bool(counsel or re.search(r"\bchief legal\b", t) or "clo" in words)
        return TitleClass("c_level", function, also_founder=founder, legal_chief=legal_chief)

    if re.search(r"\b(?:vice president|vp|svp|evp|avp)\b", t):
        return TitleClass("vp", function_for(t), also_founder=founder)
    if re.search(r"\bhead\b", t):
        return TitleClass("head", function_for(t), also_founder=founder)
    if founder:
        return TitleClass("founder", function_for(t.replace("founder", "")))
    return None

